# %% import libraries
import matplotlib.pyplot as plt
import numpy as np
import bemcs
import pandas as pd
import bemcs.bemAssembly as GF
import warnings

# Suppress all warnings
warnings.filterwarnings("ignore")


# %% Read source file and mesh of the domain
# case 1: homogeneous domain with a fault
# fileinput = "testing_mesh.csv"

# case 2: heterogeneous domain (need to provide connectivity file for force elements)
# Both files below are generated by running ConstructMesh.py in this folder first.
fileinput = "HeterogeneousDomainMesh.csv"
connectvitiyfile = "HeterogeneousDomainMeshConnectivity.csv"
connmatrix = pd.read_csv(connectvitiyfile, header=None).values
# %% solve BEM to get quadratic(slip) & force coefficients
if "connmatrix" in locals():
    els, els_s, quadcoefs, forcecoefs = GF.solveAntiplaneBEM(
        fileinput, connectvitiyfile
    )
else:
    els, els_s, quadcoefs, _ = GF.solveAntiplaneBEM(fileinput)

# %% compute and plot displacement, displacement gradient fields inside the domain
n_els = len(els.x1)
xlimits = [-4, 4]
ylimits = [-2, 0]
nx_obs = 200
ny_obs = 100
x_obs = np.linspace(-5, 5, nx_obs)
y_obs = np.linspace(-6, -1e-3, ny_obs)
x_obs, y_obs = np.meshgrid(x_obs, y_obs)
xo = x_obs.flatten().reshape(-1, 1)
yo = y_obs.flatten().reshape(-1, 1)
# compute kernels at observation points: quadratic slip on the slip elements
U_s, S_s, _ = bemcs.get_slip_kernels(xo, yo, els_s, geometry="antiplane", mu=1.0)

# compute displacement and stress components
u = U_s[:, :, 0] @ quadcoefs
sx = S_s[:, :, 0] @ quadcoefs
sy = S_s[:, :, 1] @ quadcoefs
if "connmatrix" in locals():
    # trapezoidal force basis on the interface ('h') elements
    U_f, S_f, _ = bemcs.get_force_kernels(
        xo, yo, els, geometry="antiplane", mu=1.0,
        basis="trapezoid", connectivity=connmatrix.astype(int),
    )
    u += U_f[:, :, 0] @ forcecoefs
    sx += S_f[:, :, 0] @ forcecoefs
    sy += S_f[:, :, 1] @ forcecoefs


# %% plot fields inside the domain
plt.figure(figsize=(10, 10))
plt.subplot(3, 1, 1)
toplot = u.reshape(ny_obs, nx_obs)
maxval = 0.5
GF.plot_BEM_field(
    toplot, els, xo, yo, xlimits, ylimits, maxval, n_levels=11, cmap="coolwarm"
)
plt.title("Displacement field $u$")

plt.subplot(3, 1, 2)
toplot = sx.reshape(ny_obs, nx_obs)
maxval = 1
GF.plot_BEM_field(
    toplot, els, xo, yo, xlimits, ylimits, maxval, n_levels=11, cmap="RdYlBu_r"
)
plt.title("Displacement gradient $u_{,x}$")

plt.subplot(3, 1, 3)
toplot = sy.reshape(ny_obs, nx_obs)
GF.plot_BEM_field(
    toplot, els, xo, yo, xlimits, ylimits, maxval, n_levels=11, cmap="RdYlBu_r"
)
plt.title("Displacement gradient $u_{,y}$")
plt.show()

# %% plot fields at the surface of the domain
plt.figure(figsize=(8, 10))
plt.subplot(2, 1, 1)
index = yo == np.max(yo)
plt.plot(xo[index], u[index], "-")
plt.xlabel("x ")
plt.ylabel("u")
plt.grid()
plt.title("Surface displacement")
plt.xlim(xlimits)
plt.subplot(2, 1, 2)
plt.plot(xo[index], sx[index], "-", label="$u_{,x}$")
plt.plot(xo[index], sy[index], "-", label="$u_{,y}$")
plt.xlabel("x ")
plt.ylabel("displacement gradients")
plt.grid()
plt.title("Surface displacement gradients")
plt.legend()
plt.xlim(xlimits)
# plt.ylim([-10, 10])
plt.show()

# %% plot slip on 's' mesh elements

xf, yf, slipnodes = GF.values_on_elements(
    els_s, quadcoefs, kind="slip", geometry="antiplane", n_eval=10
)
plt.figure(figsize=(4, 4))
# plt.subplot2grid((1, 3), (0, 0), colspan=2)
# plt.plot(xf[yf == 0], slipnodes[yf == 0], "-")
# plt.xlabel("x")
# plt.ylabel("slip at nodes")
# plt.xlim(xlimits)
# plt.grid()
# plt.subplot2grid((1, 3), (0, 2))
plt.plot(slipnodes[yf < 0], yf[yf < 0], ".-")
plt.ylabel("y")
plt.xlabel("slip at nodes")
plt.grid()
plt.show()
# %% end of file
